3	// Regression coverage for the byte offsets carried by character-integrity
4	// failures. A consumer of the per-line failure records gets one error string
5	// with an "at byte offset N" position; these tests pin what N means so the
6	// consumer can slice the raw input at N and land exactly on the corruption:
7	//
8	//   - N is a zero-based byte offset into the line content AFTER the legal
9	//     JSON document whitespace (space, tab, CR, LF) around the object is
10	//     trimmed — not an offset into the whole input stream, and not a
11	//     terminal display column.
12	//   - N counts raw input bytes: Chinese text, emoji, and legal escape
13	//     sequences before the corruption contribute their on-the-wire byte
14	//     length, never a display character count or a decoded string length,
15	//     and nested unknown-field content is located from the line start, not
16	//     from the field value or an inner object.
17	//   - Invalid UTF-8 points at the first byte that cannot form a legal
18	//     character (the start of a truncated multi-byte sequence); an unpaired
19	//     surrogate escape points at the backslash opening the escape, and the
20	//     message distinguishes a lone high surrogate from a lone low one.
21	//   - Correctly paired escapes and plain "uD800" text behind an escaped
22	//     backslash are not corruption and must not shift the offset of a real
23	//     problem later in the same line; invalid UTF-8 outranks an unpaired
24	//     escape even when the escape sits earlier in the line.
25	//
26	// The tests only observe NormalizeReader's public records; the normalization
27	// behavior itself is unchanged.
28	
29	import (
30		"bytes"
31		"regexp"
32		"strconv"
33		"strings"
34		"testing"
35		"unicode/utf8"
36	)
37	
38	// byteOffsetPattern extracts the position a character-integrity failure
39	// reports for its corruption point.
40	var byteOffsetPattern = regexp.MustCompile(`at byte offset ([0-9]+)`)
41	
42	// reportedOffset parses the byte offset out of a failure record's error,
43	// failing the test when the error carries no position.
44	func reportedOffset(t *testing.T, msg string) int {
45		t.Helper()
46		m := byteOffsetPattern.FindStringSubmatch(msg)
47		if m == nil {
48			t.Fatalf("error %q must carry an \"at byte offset N\" position", msg)
49		}
50		offset, err := strconv.Atoi(m[1])
51		if err != nil {
52			t.Fatalf("parsing offset from %q: %v", msg, err)
53		}
54		return offset
55	}
56	
57	// trimJSONDocumentWhitespace mirrors the normalizer's own trimming, so tests
58	// can express expectations against the same content the offset counts from:
59	// the JSON document on the line, without the legal whitespace around it.
60	func trimJSONDocumentWhitespace(line string) []byte {
61		return bytes.Trim([]byte(line), " \t\r\n")
62	}
63	
64	// requireOffsetPointsAt asserts the reported offset is exactly the byte
65	// index of marker within the trimmed line content: a consumer slicing the
66	// raw input at the reported position lands on the corruption itself.
67	func requireOffsetPointsAt(t *testing.T, trimmed []byte, offset int, marker string) {
68		t.Helper()
69		want := bytes.Index(trimmed, []byte(marker))
70		if want < 0 {
71			t.Fatalf("test bug: marker %q not found in %q", marker, trimmed)
72		}
73		if offset != want {
74			t.Fatalf("offset must locate %q at byte %d of the trimmed line content, got %d", marker, want, offset)
75		}
76		if !bytes.HasPrefix(trimmed[offset:], []byte(marker)) {
77			t.Fatalf("slicing the input at offset %d must land on %q, got %q", offset, marker, trimmed[offset:])
78		}
79	}
80	
81	// expectOffsetFailure normalizes input as a one-line stream and requires
82	// exactly one failure record — line 1, ok:false, one error, no event — whose
83	// error carries a byte offset. It returns the error message and the offset.
84	func expectOffsetFailure(t *testing.T, input string) (string, int) {
85		t.Helper()
86		var out bytes.Buffer
87		failures, err := NormalizeReader(strings.NewReader(input), &out)
88		if err != nil {
89			t.Fatalf("a corrupted log line is not a stream error, got %v", err)
90		}
91		if failures != 1 {
92			t.Fatalf("the corrupted line must count as one failure, got %d", failures)
93		}
94		if !utf8.Valid(out.Bytes()) {
95			t.Fatalf("output must be valid UTF-8 even for corrupted input: %q", out.Bytes())
96		}
97		results := decodeResults(t, out.Bytes())
98		if len(results) != 1 {
99			t.Fatalf("expected exactly one result, got %#v", results)
100		}
101		r := results[0]
102		if r["line"] != float64(1) || r["ok"] != false {
103			t.Fatalf("the corrupted line must fail as line 1: %#v", r)
104		}
105		if _, exists := r["event"]; exists {
106			t.Fatalf("a character-corrupted line must not emit an event: %#v", r)
107		}
108		msg, _ := r["error"].(string)
109		if msg == "" {
110			t.Fatalf("the failure record must explain itself: %#v", r)
111		}
112		return msg, reportedOffset(t, msg)
113	}
114	
115	// The offset counts from the first byte of the JSON document on the line:
116	// spaces, tabs, and carriage returns around the object are trimmed away and
117	// must not move the reported position of the same corruption point, while
118	// the same characters between tokens inside the object occupy real bytes and
119	// do move it.
120	func TestNormalizeOffsetStartsAtTrimmedLineContent(t *testing.T) {
121		corrupted := `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800"}`
122		base := bytes.Index([]byte(corrupted), []byte(`\uD800`))
123	
124		variants := []struct {
125			name  string
126			input string
127		}{
128			{"no surrounding whitespace", corrupted},
129			{"leading space", " " + corrupted},
130			{"leading tabs", "\t\t" + corrupted},
131			{"leading carriage return", "\r" + corrupted},
132			{"mixed leading and trailing whitespace", " \t\r" + corrupted + " \t"},
133			{"leading spaces and trailing carriage return", "  " + corrupted + "\r"},
134		}
135		for _, tc := range variants {
136			t.Run(tc.name, func(t *testing.T) {
137				msg, offset := expectOffsetFailure(t, tc.input+"\n")
138				if !strings.Contains(msg, "unpaired") {
139					t.Fatalf("expected an unpaired escape failure, got %q", msg)
140				}
141				if offset != base {
142					t.Fatalf("whitespace around the object must not move the offset %d, got %d", base, offset)
143				}
144				requireOffsetPointsAt(t, trimJSONDocumentWhitespace(tc.input), offset, `\uD800`)
145			})
146		}
147	
148		t.Run("whitespace inside the object still occupies bytes", func(t *testing.T) {
149			// Two extra spaces after "{" and one tab before "action" sit inside
150			// the document: the same corruption point moves by exactly those
151			// three bytes. The tab counts as one byte, not a display column.
152			spaced := "{  \"timestamp\":\"2026-01-02T00:00:00Z\",\t\"action\":\"\\uD800\" }"
153			_, offset := expectOffsetFailure(t, spaced+"\n")
154			if offset != base+3 {
155				t.Fatalf("internal whitespace must count as bytes: want offset %d, got %d", base+3, offset)
156			}
157			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(spaced), offset, `\uD800`)
158		})
159	}
160	
161	// Content before the corruption point contributes its raw input byte length:
162	// Chinese characters are three bytes each, an emoji four, and a legal
163	// \uXXXX escape six — never a display character count and never the length
164	// of the string those bytes decode to.
165	func TestNormalizeOffsetCountsInputBytesNotCharacters(t *testing.T) {
166		cases := []struct {
167			name           string
168			action         string
169			marker         string
170			multibyteAhead bool // raw multi-byte characters precede the corruption
171		}{
172			{"Chinese text before the bad escape", `登录\uD800`, `\uD800`, true},
173			{"emoji before the bad escape", `😀\uDC00`, `\uDC00`, true},
174			// A legal BMP escape is six raw bytes decoding to one character; the
175			// bad escape sits after those six bytes, not after one.
176			{"legal BMP escape before the bad escape", `\u0041\uD800`, `\uD800`, false},
177			// A paired surrogate escape is twelve raw bytes decoding to a single
178			// astral character; neither twelve-to-one nor twelve-to-four
179			// rewrites may apply.
180			{"paired surrogate escape before the bad escape", `\uD83D\uDE00\uD800`, `\uD800`, false},
181		}
182		for _, tc := range cases {
183			t.Run(tc.name, func(t *testing.T) {
184				input := `{"timestamp":"2026-01-02T00:00:00Z","action":"` + tc.action + `"}`
185				_, offset := expectOffsetFailure(t, input+"\n")
186				trimmed := trimJSONDocumentWhitespace(input)
187				requireOffsetPointsAt(t, trimmed, offset, tc.marker)
188				if tc.multibyteAhead {
189					if runes := utf8.RuneCount(trimmed[:offset]); runes == offset {
190						t.Fatalf("offset %d must count bytes, not display characters", offset)
191					}
192				}
193			})
194		}
195	}
196	
197	// Corruption inside an unknown field's nested object or array is located
198	// from the start of the whole line, exactly like corruption in a mapped
199	// field — never re-anchored to the field value or to the inner object.
200	func TestNormalizeOffsetInNestedExtraIsLineRelative(t *testing.T) {
201		t.Run("unpaired escape deep in a nested object", func(t *testing.T) {
202			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","extra":{"deep":["ok","\uD800"]}}`
203			_, offset := expectOffsetFailure(t, input+"\n")
204			trimmed := trimJSONDocumentWhitespace(input)
205			requireOffsetPointsAt(t, trimmed, offset, `\uD800`)
206			inner := bytes.Index(trimmed, []byte(`"deep"`))
207			if inner < 0 || offset <= inner {
208				t.Fatalf("offset %d must reach past the nested container at %d into the line", offset, inner)
209			}
210		})
211		t.Run("invalid UTF-8 deep in a nested array", func(t *testing.T) {
212			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"a","payload":{"list":["ok","` + "\xff" + `"]}}`
213			msg, offset := expectOffsetFailure(t, input+"\n")
214			if !strings.Contains(msg, "UTF-8") {
215				t.Fatalf("expected an invalid UTF-8 failure, got %q", msg)
216			}
217			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(input), offset, "\xff")
218		})
219	}
220	
221	// An invalid UTF-8 failure points at the first byte that cannot start or
222	// continue a legal character. A multi-byte sequence missing its continuation
223	// bytes is reported at the byte where that sequence begins.
224	func TestNormalizeInvalidUTF8OffsetPointsAtFirstBadByte(t *testing.T) {
225		cases := []struct {
226			name   string
227			input  string
228			marker string
229		}{
230			{"lone continuation byte after the object",
231				`{"timestamp":"2026-01-02T00:00:00Z","action":"a"}` + "\x80", "\x80"},
232			{"invalid byte inside a string value",
233				`{"timestamp":"2026-01-02T00:00:00Z","action":"log` + "\xff" + `in"}`, "\xff"},
234			{"truncated three-byte sequence before the closing quote",
235				`{"timestamp":"2026-01-02T00:00:00Z","action":"ab` + "\xe2\x80" + `"}`, "\xe2\x80"},
236			{"truncated sequence at the end of the input",
237				`{"timestamp":"2026-01-02T00:00:00Z","action":"ab` + "\xe2\x80", "\xe2\x80"},
238			{"overlong encoding",
239				`{"timestamp":"2026-01-02T00:00:00Z","action":"` + "\xc0\xaf" + `"}`, "\xc0\xaf"},
240			{"UTF-8 encoded surrogate",
241				`{"timestamp":"2026-01-02T00:00:00Z","action":"` + "\xed\xa0\x80" + `"}`, "\xed\xa0\x80"},
242			{"valid multi-byte text before the bad byte",
243				`{"timestamp":"2026-01-02T00:00:00Z","action":"登录😀` + "\xff" + `"}`, "\xff"},
244		}
245		for _, tc := range cases {
246			t.Run(tc.name, func(t *testing.T) {
247				msg, offset := expectOffsetFailure(t, tc.input+"\n")
248				if !strings.Contains(msg, "invalid UTF-8 encoding") {
249					t.Fatalf("expected an invalid UTF-8 failure, got %q", msg)
250				}
251				if strings.Contains(msg, "surrogate") {
252					t.Fatalf("UTF-8 corruption must not be reported as an escape problem, got %q", msg)
253				}
254				requireOffsetPointsAt(t, trimJSONDocumentWhitespace(tc.input), offset, tc.marker)
255			})
256		}
257	}
258	
259	// An unpaired surrogate escape points at the backslash that opens the
260	// escape, and the reason distinguishes a lone high surrogate from a lone low
261	// one so the consumer can tell the two corruption shapes apart.
262	func TestNormalizeSurrogateEscapeOffsetPointsAtBackslash(t *testing.T) {
263		cases := []struct {
264			name    string
265			action  string
266			marker  string // raw escape text whose backslash is the corruption point
267			kind    string // distinctive phrase for the surrogate kind
268			spelled string // the escape as spelled in the error message
269		}{
270			{"lone high surrogate", `\uD800`, `\uD800`,
271				"high surrogate must be followed immediately", `\uD800`},
272			{"lone low surrogate", `act\uDC00ion`, `\uDC00`,
273				"low surrogate must follow a high surrogate escape", `\uDC00`},
274			// A reversed pair fails on the low surrogate that comes first.
275			{"reversed surrogate pair", `\uDC00\uD800`, `\uDC00`,
276				"low surrogate must follow a high surrogate escape", `\uDC00`},
277			// The first of two adjacent high surrogates is already unpaired.
278			{"high surrogate before a completed pair", `\uD800\uD800\uDC00`, `\uD800`,
279				"high surrogate must be followed immediately", `\uD800`},
280			{"high surrogate followed by a BMP escape", `\uD800A`, `\uD800`,
281				"high surrogate must be followed immediately", `\uD800`},
282			{"low surrogate boundary values", `x\uDFFFy`, `\uDFFF`,
283				"low surrogate must follow a high surrogate escape", `\uDFFF`},
284		}
285		for _, tc := range cases {
286			t.Run(tc.name, func(t *testing.T) {
287				input := `{"timestamp":"2026-01-02T00:00:00Z","action":"` + tc.action + `"}`
288				msg, offset := expectOffsetFailure(t, input+"\n")
289				if !strings.Contains(msg, "unpaired Unicode escape "+tc.spelled) {
290					t.Fatalf("error must name the unpaired escape %s, got %q", tc.spelled, msg)
291				}
292				if !strings.Contains(msg, tc.kind) {
293					t.Fatalf("error must identify the surrogate kind %q, got %q", tc.kind, msg)
294				}
295				if strings.Contains(msg, "UTF-8") {
296					t.Fatalf("an unpaired escape must not be reported as UTF-8 corruption, got %q", msg)
297				}
298				requireOffsetPointsAt(t, trimJSONDocumentWhitespace(input), offset, tc.marker)
299			})
300		}
301	}
302	
303	// Legal lookalikes are neither flagged themselves nor miscounted: a
304	// correctly paired surrogate escape, plain "uD800" text behind an escaped
305	// backslash, and a literal U+FFFD leave the offset of a real corruption
306	// later in the same line exactly at that corruption's own byte index.
307	func TestNormalizeLegalLookalikesDoNotShiftCorruptionOffset(t *testing.T) {
308		t.Run("unpaired escape after legal lookalikes", func(t *testing.T) {
309			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"ok",` +
310				`"pair":"\uD83D\uDE00","text":"\\uD800","mark":"�","bad":"\uDC00"}`
311			msg, offset := expectOffsetFailure(t, input+"\n")
312			if !strings.Contains(msg, "unpaired") || !strings.Contains(msg, "low surrogate") {
313				t.Fatalf("the lone low surrogate must be the reported problem, got %q", msg)
314			}
315			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(input), offset, `\uDC00`)
316		})
317		t.Run("invalid UTF-8 after legal lookalikes", func(t *testing.T) {
318			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"ok",` +
319				`"pair":"\uD83D\uDE00","text":"\\uD800","bad":"` + "\xff" + `"}`
320			msg, offset := expectOffsetFailure(t, input+"\n")
321			if !strings.Contains(msg, "UTF-8") {
322				t.Fatalf("the invalid byte must be the reported problem, got %q", msg)
323			}
324			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(input), offset, "\xff")
325		})
326	}
327	
328	// When one line carries both an unpaired escape and invalid UTF-8, the
329	// reported problem is the UTF-8 corruption and the reported position is the
330	// bad byte's own offset — even when the escape sits earlier in the line.
331	func TestNormalizeUTF8OffsetReportedEvenWhenEscapeIsEarlier(t *testing.T) {
332		t.Run("escape before the invalid byte", func(t *testing.T) {
333			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800` + "\xff" + `"}`
334			msg, offset := expectOffsetFailure(t, input+"\n")
335			if !strings.Contains(msg, "invalid UTF-8 encoding") || strings.Contains(msg, "surrogate") {
336				t.Fatalf("invalid UTF-8 must outrank the unpaired escape, got %q", msg)
337			}
338			trimmed := trimJSONDocumentWhitespace(input)
339			requireOffsetPointsAt(t, trimmed, offset, "\xff")
340			if escapeAt := bytes.Index(trimmed, []byte(`\uD800`)); offset <= escapeAt {
341				t.Fatalf("offset %d must pass the earlier escape at %d and land on the bad byte", offset, escapeAt)
342			}
343		})
344		t.Run("invalid byte before the escape", func(t *testing.T) {
345			input := `{"timestamp":"2026-01-02T00:00:00Z","action":"` + "\xff" + `\uD800"}`
346			msg, offset := expectOffsetFailure(t, input+"\n")
347			if !strings.Contains(msg, "invalid UTF-8 encoding") || strings.Contains(msg, "surrogate") {
348				t.Fatalf("invalid UTF-8 must outrank the unpaired escape, got %q", msg)
349			}
350			requireOffsetPointsAt(t, trimJSONDocumentWhitespace(input), offset, "\xff")
351		})
352	}
353	
354	// In a stream, every offset is relative to its own line: valid logs and
355	// blank lines before a corrupted line advance the physical line number
356	// without adding a single byte to the reported position. Only the corrupted
357	// lines fail — each with one error and no event — later valid lines keep
358	// coming out in order, and the returned failure count covers exactly the
359	// corrupted lines.
360	func TestNormalizeStreamOffsetsArePerLineWithPhysicalLineNumbers(t *testing.T) {
361		escapeLine := `{"timestamp":"2026-01-02T00:00:00Z","action":"\uD800"}`
362		utf8Line := `{"timestamp":"2026-01-02T00:00:00Z","action":"bad` + "\xff" + `"}`
363		input := `{"timestamp":"2026-01-02T00:00:00Z","action":"first"}` + "\n" +
364			"\n" +
365			"  " + escapeLine + "\n" + // leading spaces: trimmed per line
366			utf8Line + "\n" +
367			`{"timestamp":"2026-01-02T00:00:02Z","action":"last"}` + "\n"
368	
369		var out bytes.Buffer
370		failures, err := NormalizeReader(strings.NewReader(input), &out)
371		if err != nil {
372			t.Fatalf("per-line corruption is not a stream error, got %v", err)
373		}
374		if failures != 2 {
375			t.Fatalf("exactly the two corrupted lines must count, got %d", failures)
376		}
377		if !utf8.Valid(out.Bytes()) {
378			t.Fatalf("output must be valid UTF-8: %q", out.Bytes())
379		}
380		results := decodeResults(t, out.Bytes())
381		if len(results) != 4 {
382			t.Fatalf("the blank line produces no output; expected 4 results, got %#v", results)
383		}
384	
385		if results[0]["line"] != float64(1) || results[0]["ok"] != true {
386			t.Fatalf("line 1 must succeed: %#v", results[0])
387		}
388	
389		// Line 3: the unpaired escape. Its offset counts from this line's own
390		// trimmed content — the two leading spaces and every byte of the earlier
391		// lines contribute nothing.
392		r := results[1]
393		if r["line"] != float64(3) || r["ok"] != false {
394			t.Fatalf("line 3 must fail with its physical line number: %#v", r)
395		}
396		if len(r) != 3 {
397			t.Fatalf("a failure record carries exactly line, ok and one error, got %#v", r)
398		}
399		if _, exists := r["event"]; exists {
400			t.Fatalf("line 3 must not emit an event: %#v", r)
401		}
402		msg, _ := r["error"].(string)
403		if !strings.Contains(msg, "unpaired") {
404			t.Fatalf("line 3 must be reported as an unpaired escape, got %q", msg)
405		}
406		requireOffsetPointsAt(t, trimJSONDocumentWhitespace(escapeLine), reportedOffset(t, msg), `\uD800`)
407	
408		// Line 4: the invalid UTF-8 byte, located within its own line.
409		r = results[2]
410		if r["line"] != float64(4) || r["ok"] != false {
411			t.Fatalf("line 4 must fail with its physical line number: %#v", r)
412		}
413		if _, exists := r["event"]; exists {
414			t.Fatalf("line 4 must not emit an event: %#v", r)
415		}
416		msg, _ = r["error"].(string)
417		if !strings.Contains(msg, "invalid UTF-8 encoding") {
418			t.Fatalf("line 4 must be reported as UTF-8 corruption, got %q", msg)
419		}
420		requireOffsetPointsAt(t, trimJSONDocumentWhitespace(utf8Line), reportedOffset(t, msg), "\xff")
421	
422		// Line 5: normalization continues after the corrupted lines.
423		if results[3]["line"] != float64(5) || results[3]["ok"] != true {
424			t.Fatalf("line 5 must still be processed: %#v", results[3])
425		}
426		if eventOf(t, results[3])["action"] != "last" {
427			t.Fatalf("input order must be preserved after corrupted lines: %#v", results[3])
428		}
429	}
